{"file_path": "services/report/languages/node.py", "original_signature": "def matches_content(self, content, first_line, name):", "target_file": {"ok": true, "path": "services/report/languages/node.py", "sha": "ca123dd0a0c237e4cb451939c028247b12d4828c", "download_url": "https://raw.githubusercontent.com/codecov/worker/92f4bd73a1e976001b78283dd58d450435760f57/services/report/languages/node.py", "content_excerpt": "from collections import defaultdict
from fractions import Fraction

from covreports.resources import Report, ReportFile
from covreports.utils.tuples import ReportLine
from covreports.utils.merge import partials_to_line
from covreports.helpers.yaml import walk

from services.report.languages.base import BaseLanguageProcessor


class NodeProcessor(BaseLanguageProcessor):

    def matches_content(self, content, first_line, name):
        return True  # TODO: fix this

    def process(self, name, content, path_fixer, ignored_lines, sessionid, repo_yaml=None):
        config = walk(repo_yaml, ('parsers', 'javascript')) or {}
        return from_json(content, path_fixer, ignored_lines, sessionid, config)


def get_line_coverage(location, cov, line_type):
    if location.get('skip'):
        return None, None, None

    sl, sc, el, ec = get_location(location)

    if not sl or sc+1 == ec:
        return None, None, None

    if line_type != 'm' and sl == el and sc != 0:
        partial = [sc, ec, cov]
    else:
        partial = None

    return sl, cov, partial


def get_location(node):
    try:
        if 'loc' in node:
            return (
              node['loc']['start']['line'],
              node['loc']['start']['column'],
              node['loc']['end']['line'],
              node['loc']['end']['column']
            )
        elif 'start' in node:
            return (
              node['start']['line'],
              node['start']['column'],
              node['end']['line'],
              node['end']['column']
            )
        else:
            return (
              node['locations'][0]['start']['line'],
              node['locations'][0]['start']['column'],
              node['locations'][-1]['end']['line'],
              node['locations'][-1]['end']['column']
            )
    except Exception:
        return (None, None, None, None)


def must_be_dict(value):
    if type(value) is not dict:
        return {}
    else:
        return value


def next_from_json(report_dict, fix, ignored_lines, sessionid, config):
    report = Report()
    for filename, data in report_dict.items():
        name = fix(filename)
        if name is None:
            name = fix(filename.replace('lib/', 'src/', 1))
            if name is None:
                continue

        _file = ReportFile(name, ignore=ignored_lines.get(name))

        if 'lineData' in data:
            jscoverage(_file, data, sessionid)
            report.append(_file)
            continue

        print(data)
        if data.get('data'):
            # why. idk. node is like that.
