        def quote(s):
            if '$' not in s:
                return pipes.quote(s)
            return s
        if isinstance(value, (list, tuple)):
            value = ' '.join(quote(x) for x in value)
        return str(value)

    def comment(self, value):
        # TODO: handle newlines
        return "# %s" % value

    def source(self, value):
        return 'source "%s"' % os.path.expanduser(value)
