{"file_path": "plom_server/Progress/services/manage_discard.py", "original_signature": "def _discard_mobile_page(self, user_obj: User, mpage_obj: MobilePage) -> None:", "target_file": {"ok": true, "path": "plom_server/Progress/services/manage_discard.py", "sha": "515108621a1af028457d00841d234a834ceea9ac", "download_url": "https://raw.githubusercontent.com/plomgrading/plom/ccdecfdffb44f9c05e7ffa2f2b7ebf5107ceee52/plom_server/Progress/services/manage_discard.py", "content_excerpt": "# SPDX-License-Identifier: AGPL-3.0-or-later
