            high_level_trigger = True;
        
        elif ( (values[index] < amplitute_threshold) and (high_level_trigger is True) ):
            high_level_trigger = False;
            
    return number_oscillations;", "total_lines": 231, "ref": "d7cb0265a93c968ba185b27efece3a2272108cbb"}, "target_function": {"found": true, "symbol_name": "legion_state", "class_name": "legion_network", "start_line": 190, "end_line": 217, "satd_line": 199, "matched_by": "normalized_source", "source": "    def legion_state(self, inputs, t, argv):
