        """
        flt = float.__new__(cls, myfloat)
        if flt < 1.0:
            raise ValueError("Distance cutoff should be between 1.0 and +infinity")
        return flt

    def as_dict(self):
        """MSONAble dict"""
        return {
            "@module": self.__class__.__module__,
            "@class": self.__class__.__name__,
            "value": self,
        }

    @classmethod
    def from_dict(cls, d):
        """From dict"""
        return cls(d["value"])


