CONFIG_FILE = os.path.join(dirs.user_data_dir, 'config')

options = {
    'widget_set': {'values': '["tk", "ttk"]', 'default':'ttk'},
    'widget_palette': {'values': '["accordion", "treeview"]', 'default':'accordion'}
}

SEC_GENERAL = 'GENERAL'
