class RPMDBPackageSack:

    def __init__(self, ts=None):
        self.excludes = {}
        self.ts = ts
        self.pkglist = []
        self.dep_table = { 'requires'  : (rpm.RPMTAG_REQUIRENAME,
                                          rpm.RPMTAG_REQUIREVERSION,
                                          rpm.RPMTAG_REQUIREFLAGS),
